 side.Dock=DockStyle.Left;side.Width=215;side.BackColor=Color.FromArgb(12,19,32);Controls.Add(side);page.Dock=DockStyle.Fill;page.AutoScroll=true;page.BackColor=bg;Controls.Add(page);page.BringToFront();
