 for(int i=0;i<names.Length;i++){int n=i;var b=Button(names[i],false);b.SetBounds(12,130+i*57,190,47);b.TextAlign=ContentAlignment.MiddleLeft;b.Click+=(s,e)=>Navigate(actions[n]);side.Controls.Add(b);}
