 static string Wmi(string cls,string prop){try{using(var s=new ManagementObjectSearcher("SELECT "+prop+" FROM "+cls)){foreach(ManagementObject o in s.Get())return Convert.ToString(o[prop]);}}catch{}return "нет данных";}
 static string Hardware(){return "Производитель: "+Wmi("Win32_ComputerSystem","Manufacturer")+"\r\nМодель: "+Wmi("Win32_ComputerSystem","Model")+"\r\nСерийный номер: "+Wmi("Win32_BIOS","SerialNumber")+"\r\nBIOS: "+Wmi("Win32_BIOS","SMBIOSBIOSVersion")+"\r\nWindows: "+Wmi("Win32_OperatingSystem","Caption")+"\r\nПроцессор: "+Wmi("Win32_Processor","Name");}
 static string ProblemDevices(){try{var lines=new List<string>();using(var s=new ManagementObjectSearcher("SELECT Name,ConfigManagerErrorCode FROM Win32_PnPEntity WHERE ConfigManagerErrorCode <> 0")){foreach(ManagementObject o in s.Get())lines.Add(Convert.ToString(o["Name"])+" — код "+Convert.ToString(o["ConfigManagerErrorCode"]));}return lines.Count==0?"Ошибки устройств не обнаружены. Проверьте также работу сети, звука и других устройств.":String.Join("\r\n",lines.Take(100));}catch(Exception e){return "Ошибка чтения устройств: "+e.Message;}}
 string IsoFolder(){string config=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MoOLVa");string pref=Path.Combine(config,"iso-folder.txt");try{if(File.Exists(pref)){string p=File.ReadAllText(pref).Trim();if(Directory.Exists(p))return p;}}catch{}string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"MoOLVa ISO");Directory.CreateDirectory(root);return root;}
 void SetIsoFolder(string path){string config=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MoOLVa");Directory.CreateDirectory(config);File.WriteAllText(Path.Combine(config,"iso-folder.txt"),path);}
 void RememberIso(string path){if(String.IsNullOrWhiteSpace(path))return;selectedIso=path;try{string config=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MoOLVa");Directory.CreateDirectory(config);string f=Path.Combine(config,"iso-history.txt");var items=File.Exists(f)?File.ReadAllLines(f).Where(File.Exists).ToList():new List<string>();items.RemoveAll(x=>String.Equals(x,path,StringComparison.OrdinalIgnoreCase));items.Insert(0,path);File.WriteAllLines(f,items.Take(30));}catch{}}
 IEnumerable<string> RecentIso(){var items=new List<string>();try{string f=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MoOLVa","iso-history.txt");if(File.Exists(f))items.AddRange(File.ReadAllLines(f).Where(File.Exists));items.AddRange(Directory.GetFiles(IsoFolder(),"*.iso"));}catch{}return items.Distinct(StringComparer.OrdinalIgnoreCase).Take(30);}
 void StartIsoBrowser(string version){try{using(var browser=new IsoBrowser(version,IsoFolder(),RememberIso)){browser.ShowDialog(this);}}catch(Exception e){MessageBox.Show("Не удалось открыть страницу Microsoft: "+e.Message);}}
 void WindowsPage(){var f=BeginPage("Windows 10 / 11 и флешка","Выберите ISO в приложении, скачайте его с Microsoft и запишите на USB.");
 AddButton(f,"Скачать ISO Windows 11 внутри MoOLVa",()=>StartIsoBrowser("11"),true);
